INSERT INTO `blogs` VALUES (1,'2026 Burs Rehberi: T├╝m Ba┼şvurular ve Tarihler','burs-rehberi-2026.html','','burs ba┼şvuru 2026, KYK burs, T├£B─░TAK burs, vak─▒f bursu, ├Â─şrenci burs rehberi','<a href=\"../blog.php\" class=\"blog-back\">ÔåÉ Blog\'a D├Ân</a>\r\n\r\n        <header class=\"blog-article-header\">\r\n            <div class=\"blog-article-tag\">­şôØ Blog Yaz─▒s─▒</div>\r\n            <h1>2026 Burs Rehberi: T├╝m Ba┼şvurular ve Tarihler</h1>\r\n            <div class=\"blog-article-meta\">\r\n                <span>­şùô´©Å February 2026</span>\r\n                <span>ÔÅ▒´©Å Okuma s├╝resi hesaplan─▒yor...</span>\r\n            </div>\r\n        </header>\r\n\r\n        \r\n        \r\n        <div class=\"blog-toc\">\r\n            <div class=\"blog-toc-title\">­şôï ─░├ğindekiler</div>\r\n            <ol>\r\n                <li><a href=\"#kyk\">KYK Burs ve Kredi</a></li>\r\n                <li><a href=\"#tubitak\">T├£B─░TAK Burslar─▒</a></li>\r\n                <li><a href=\"#vakif\">Vak─▒f Burslar─▒</a></li>\r\n                <li><a href=\"#ozel\">├ûzel Sekt├Âr Burslar─▒</a></li>\r\n                <li><a href=\"#basvuru\">Ba┼şvuru Stratejileri</a></li>\r\n            </ol>\r\n        </div>\r\n\r\n        <p>T├╝rkiye\'de ├╝niversite ├Â─şrencileri i├ğin y├╝zlerce burs f─▒rsat─▒ bulunuyor. Ancak ├ğo─şu ├Â─şrenci bunlardan habersiz\r\n            veya ba┼şvuru s├╝recini ka├ğ─▒r─▒yor. ─░┼şte <strong>2026 y─▒l─▒nda ba┼şvurabilece─şiniz</strong> en ├Ânemli burs\r\n            programlar─▒:</p>\r\n\r\n        <h2 id=\"kyk\">­şÅø´©Å KYK Burs ve Kredi</h2>\r\n\r\n        <p>KYK (Yurt-Kur), devletin en yayg─▒n ├Â─şrenci destek program─▒d─▒r:</p>\r\n\r\n        <div class=\"blog-table-wrapper\">\r\n            <table class=\"blog-table\">\r\n                <thead>\r\n                    <tr>\r\n                        <th>Program</th>\r\n                        <th>Ayl─▒k Tutar</th>\r\n                        <th>Geri ├ûdeme</th>\r\n                        <th>Ba┼şvuru</th>\r\n                    </tr>\r\n                </thead>\r\n                <tbody>\r\n                    <tr>\r\n                        <td>KYK Burs (Kar┼ş─▒l─▒ks─▒z)</td>\r\n                        <td class=\"highlight-value\">1.350 Ôé║</td>\r\n                        <td>Yok</td>\r\n                        <td>Eyl├╝l-Ekim</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>KYK Kredi (├ûn Lisans)</td>\r\n                        <td class=\"highlight-value\">1.150 Ôé║</td>\r\n                        <td>Mezuniyet + 2 y─▒l sonra</td>\r\n                        <td>Eyl├╝l-Ekim</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>KYK Kredi (Lisans)</td>\r\n                        <td class=\"highlight-value\">1.350 Ôé║</td>\r\n                        <td>Mezuniyet + 2 y─▒l sonra</td>\r\n                        <td>Eyl├╝l-Ekim</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>KYK Kredi (Y. Lisans)</td>\r\n                        <td class=\"highlight-value\">1.800 Ôé║</td>\r\n                        <td>Mezuniyet + 2 y─▒l sonra</td>\r\n                        <td>Eyl├╝l-Ekim</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>KYK Kredi (Doktora)</td>\r\n                        <td class=\"highlight-value\">2.500 Ôé║</td>\r\n                        <td>Mezuniyet + 2 y─▒l sonra</td>\r\n                        <td>Eyl├╝l-Ekim</td>\r\n                    </tr>\r\n                </tbody>\r\n            </table>\r\n        </div>\r\n\r\n        <div class=\"blog-info-box tip\">\r\n            <p>­şÆí <strong>─░pucu:</strong> KYK kredi geri ├Âdemesi faiz avantajl─▒d─▒r. Enflasyon d├╝┼ş├╝n├╝ld├╝─ş├╝nde, kredi\r\n                almak genellikle avantajl─▒d─▒r ÔÇö ├Âdeme ba┼şlad─▒─ş─▒nda anapara reel olarak k├╝├ğ├╝lm├╝┼ş olur.</p>\r\n        </div>\r\n\r\n        <h2 id=\"tubitak\">­şö¼ T├£B─░TAK Burslar─▒</h2>\r\n        <ul>\r\n            <li><strong>B─░DEB 2205 ÔÇö Yurt ─░├ği Lisans Burs:</strong> Ayl─▒k 3.500Ôé║, ba┼şar─▒ ve proje odakl─▒</li>\r\n            <li><strong>B─░DEB 2210 ÔÇö Y. Lisans Burs:</strong> Ayl─▒k 5.000Ôé║, ara┼şt─▒rma performans─▒na g├Âre</li>\r\n            <li><strong>B─░DEB 2211 ÔÇö Doktora Burs:</strong> Ayl─▒k 7.000Ôé║, yurt i├ği doktora programlar─▒</li>\r\n            <li><strong>B─░DEB 2209 ÔÇö Ara┼şt─▒rma Projesi:</strong> Yaz d├Âneminde proje yapan lisans ├Â─şrencilerine destek\r\n            </li>\r\n        </ul>\r\n\r\n        <h2 id=\"vakif\">­şÅĞ Vak─▒f Burslar─▒</h2>\r\n\r\n        <div class=\"blog-table-wrapper\">\r\n            <table class=\"blog-table\">\r\n                <thead>\r\n                    <tr>\r\n                        <th>Vak─▒f</th>\r\n                        <th>Ayl─▒k Tutar</th>\r\n                        <th>Ba┼şvuru D├Ânemi</th>\r\n                    </tr>\r\n                </thead>\r\n                <tbody>\r\n                    <tr>\r\n                        <td>Vehbi Ko├ğ Vakf─▒</td>\r\n                        <td class=\"highlight-value\">2.500-4.000 Ôé║</td>\r\n                        <td>Eyl├╝l-Kas─▒m</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>TEV (T├╝rk E─şitim Vakf─▒)</td>\r\n                        <td class=\"highlight-value\">2.000-3.500 Ôé║</td>\r\n                        <td>Eyl├╝l-Ekim</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>├çYDD</td>\r\n                        <td class=\"highlight-value\">1.500-2.500 Ôé║</td>\r\n                        <td>Eyl├╝l</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>Sabanc─▒ Vakf─▒</td>\r\n                        <td class=\"highlight-value\">2.000-3.000 Ôé║</td>\r\n                        <td>Ekim-Kas─▒m</td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td>Dar├╝┼ş┼şafaka</td>\r\n                        <td class=\"highlight-value\">2.000-4.000 Ôé║</td>\r\n                        <td>Eyl├╝l-Ekim</td>\r\n                    </tr>\r\n                </tbody>\r\n            </table>\r\n        </div>\r\n\r\n        <h2 id=\"ozel\">­şÅó ├ûzel Sekt├Âr Burslar─▒</h2>\r\n        <ul>\r\n            <li><strong>Limak Vakf─▒:</strong> M├╝hendislik ├Â─şrencilerine ayl─▒k 3.000Ôé║ + staj imk├ón─▒</li>\r\n            <li><strong>Eczac─▒ba┼ş─▒ Burs:</strong> Ayl─▒k 2.500Ôé║, STEM alanlar─▒ ├Âncelikli</li>\r\n            <li><strong>Samsung Burs:</strong> Bilgisayar/Elektronik m├╝hendisli─şine ayl─▒k 2.000Ôé║</li>\r\n            <li><strong>Turkcell Akademi:</strong> Yaz─▒l─▒m ve veri bilimi ├Â─şrencilerine burs + mentorluk</li>\r\n        </ul>\r\n\r\n        <h2 id=\"basvuru\">­şôØ Burs Ba┼şvuru Stratejileri</h2>\r\n        <ol>\r\n            <li><strong>Takvim olu┼şturun:</strong> Ba┼şvuru tarihlerini takip etmek i├ğin hat─▒rlat─▒c─▒ kurun</li>\r\n            <li><strong>├çoklu ba┼şvuru yap─▒n:</strong> Tek bir bursa de─şil, 5-10 farkl─▒ programa ba┼şvurun</li>\r\n            <li><strong>Referans mektuplar─▒n─▒z─▒ haz─▒r tutun:</strong> Hocalar─▒n─▒zdan ├Ânceden rica edin</li>\r\n            <li><strong>Motivasyon mektubunu ki┼şiselle┼ştirin:</strong> Her burs i├ğin ayr─▒, ├Âzel bir mektup yaz─▒n</li>\r\n            <li><strong>Sosyal sorumluluk projelerine kat─▒l─▒n:</strong> G├Ân├╝ll├╝ ├ğal─▒┼şmalar burs de─şerlendirmesinde art─▒\r\n                puan</li>\r\n        </ol>\r\n\r\n        <div class=\"blog-cta\">\r\n            <h3>­şôè B├╝t├ğeni Planla</h3>\r\n            <p>├£niversite hayat─▒nda b├╝t├ğeni do─şru y├Ânetmek i├ğin hemen hesaplama yap.</p>\r\n            <a href=\"../index.php#budget\" class=\"btn btn-primary\">­şôè B├╝t├ğemi Hesapla</a>\r\n        </div>','','­şôØ Blog Yaz─▒s─▒','2026-01-15 12:00:00','2026-04-17 23:17:11','published'),(3,'2026\'n─▒n En Ucuz ├û─şrenci ┼Şehirleri','en-ucuz-ogrenci-sehirleri-2026.