  `living_score` decimal(3,1) DEFAULT NULL,
  `rent_single` int(11) DEFAULT NULL,
  `rent_shared` int(11) DEFAULT NULL,
  `dorm_private` int(11) DEFAULT NULL,
  `dorm_kyk` int(11) DEFAULT 1000,
  `food` int(11) DEFAULT NULL,
  `transport` int(11) DEFAULT NULL,
  `entertainment` int(11) DEFAULT NULL,
  `utilities` int(11) DEFAULT NULL,
  `tip_1` varchar(500) DEFAULT NULL,
  `tip_2` varchar(500) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`)
) ENGINE=InnoDB AUTO_INCREMENT=82 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
